examples.code:
MonarchMarketingSection(
    title = "Every idea gets the right shape.",
    eyebrow = "The editor",
    description = "Type a slash and pick a block.",
) {
    MonarchFeatureGrid(
        items = listOf(
            MonarchFeatureGridItem(
                title = "Slash commands",
                description = "Tables, lists and callouts, one keystroke away.",
            ),
            MonarchFeatureGridItem(
                title = "Version history",
                description = "Named snapshots you can restore safely.",
            ),
        ),
        columns = 2,
    )
}

Column(verticalArrangement = Arrangement.spacedBy(40.dp)) {
    MonarchProductFrame(label = "Share dialog with a copyable link", title = "example.rookhq.com/share") {
        MonarchText(text = "Anyone with the link can view", modifier = Modifier.padding(24.dp))
    }
    MonarchStatStrip(
        items = listOf(
            MonarchStatStripItem(value = "3", label = "Export formats"),
            MonarchStatStripItem(value = "13", label = "Interface languages"),
        ),
    )
    MonarchFaq(items = listOf(MonarchFaqItem(question = "Which formats can I export?", answer = "HTML, Markdown and PDF.")))
    MonarchCtaBand(title = "Start with a blank page.") {
        MonarchButton(text = "Start writing", onClick = {}, variant = MonarchButtonVariant.Primary)
    }
}
